let input = require('readline').createInterface({ input: process.stdin });
let lines = [];
let lineIndex = 0;

input.on('line', (line) => {
    lines.push(line);
});

input.on('close', () => {
    let tokens = [];
    for (let line of lines) {
        tokens.push(...line.split(/\s+/).filter(t => t !== ''));
    }
    let tokenIndex = 0;

    function next() {
        if (tokenIndex >= tokens.length) return null;
        return tokens[tokenIndex++];
    }

    function nextLong() {
        return BigInt(next());
    }

    let n = nextLong();
    let k = nextLong();
    let l = nextLong();
    let MOD = nextLong();

    if (l !== 64n && (1n << l) - 1n < k) {
        console.log(0);
        return;
    }

    let fibCache = new Map();
    fibCache.set(0n, 1n);
    fibCache.set(1n, 1n);

    function fib(n) {
        if (fibCache.has(n)) return fibCache.get(n);
        let k = n / 2n;
        let res;
        if (n % 2n === 0n) {
            res = (fib(k) * fib(k) + fib(k - 1n) * fib(k - 1n)) % MOD;
        } else {
            res = (fib(k) * fib(k + 1n) + fib(k - 1n) * fib(k)) % MOD;
        }
        fibCache.set(n, res);
        return res;
    }

    function powerMod(a, b, m) {
        if (b === 0n) return 1n;
        if (b === 1n) return a % m;
        if (b % 2n === 0n) {
            return powerMod((a * a) % m, b / 2n, m);
        } else {
            return (a * powerMod((a * a) % m, (b - 1n) / 2n, m)) % m;
        }
    }

    let zeroPos = fib(n + 1n);
    let onePos = powerMod(2n, n, MOD) - zeroPos;
    while (onePos < 0n) onePos += MOD;

    let res = 1n;
    for (let i = 0n; i < l; i++) {
        if ((k & (1n << i)) !== 0n) {
            res = (res * onePos) % MOD;
        } else {
            res = (res * zeroPos) % MOD;
        }
    }
    console.log(res % MOD);
